        k_ch = float(kwargs.get("k_cherednik", 0.07))
        k_k = float(kwargs.get("k_kostka", 0.08))
        k_m = float(kwargs.get("k_macdonald", 0.09))
        k_a = float(kwargs.get("k_askey", 0.10))
        k_ell = float(kwargs.get("k_elliptic", 0.11))
