        k_d = float(kwargs.get("k_daha", k_daha))
        k_whit = float(kwargs.get("k_whittaker", 0.29))
        k_bor = float(kwargs.get("k_borch", 0.15))
        k_moon = float(kwargs.get("k_moonshine", 0.17))
