        daha_factor = 1.0 + k_h + k_ch
        daha_kostka_factor = 1.0 + k_h + k_ch + k_k
        daha_macdonald_factor = 1.0 + k_h + k_ch + k_k + k_m
        daha_askey_factor = 1.0 + k_h + k_ch + k_k + k_m + k_a
