        c_pcqtgbdddddd = float(kwargs.get("c_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_dunkl_hecke_cherednik_kostka", kwargs.get("c_pcqtgbdddddd", 0.000003)))
