        w_state_pcq = float(kwargs.get("w_pcq", w_pcq))
        w_state_pcqt = float(kwargs.get("w_pcqt", w_pcqt))
        w_state_pcqtg = float(kwargs.get("w_pcqtg", w_pcqtg))
