        w_state_pcqtgbdddddd = float(kwargs.get("w_pcqtgbdddddd", w_pcqtgbdddddd))
        w_state_pcqtgbddddhkm = float(kwargs.get("w_pcqtgbddddhkm", w_pcqtgbddddhkm))
