    compute_knk_pcqtgbdd_queue_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_queue_acceleration
    compute_knk_pcqtgbdd_dark_energy_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_queue_acceleration
    compute_pcqtgbdd_dark_energy_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_queue_acceleration
    compute_pcqtgbdd_queue_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_queue_acceleration
    compute_pcqtgbdd_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_queue_acceleration
    compute_12_dark_energy_queue_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_dilaton_dirac_queue_acceleration
