    # Phase 31 KNK 10-Dark-Energy Aliases
    compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_queue_acceleration
    compute_knk_phantom_chameleon_quintom_tachyon_ghost_brane_acceleration = compute_kerr_newman_kiselev_phantom_chameleon_quintom_tachyon_ghost_brane_queue_acceleration
